s=s.replace("def inspect_receipts(directory,expected):", "def inspect_receipts(directory,session):\n    expected=session['requests']")
s=s.replace("summary=load(directory/'summary.json')", "summary=load(directory/'summary.json') if (directory/'summary.json').exists() else {}")
s=s.replace("    return checks\n\ndef reset_fixture", "    if session.get('qualification'):\n        for key in ['controller_summary','expected_attempt_count','attempts_passed']:checks.pop(key,None)\n        checks['H_real_wait_echild']=supervisor.get('echild') is True and supervisor.get('controller_wait_status') is not None\n    return checks\n\ndef reset_fixture")
s=s.replace("env.update(config['numpy_thread_environment'])", "env.update(config['numpy_thread_environment']);env.update(session['extra_env']);env['COST_REQUESTS']=str(session['requests'])")
