s=s.replace("choices=['import','data','blas']", "choices=['base','import','data','blas']")
s=s.replace("if not order or len(set(order))!=len(order) or not set(order)<=set(VARIANTS):parser.error('--order must list unique supported architectures')", "matrix=json.loads(args.matrix.read_text());assert isinstance(matrix,list) and matrix\n    order=[x['group'] for x in matrix];assert set(order)<=set(VARIANTS)")
s=s.replace("    if not args.pilot and sorted(order)!=sorted(VARIANTS):parser.error('formal block requires all three groups')\n", "")
s=s.replace("        validate_numpy_scope(review,args,order)", "        for item in matrix:\n            assert item.get('admission_key') in review.get('admission_keys',[]),('configuration not admitted',item)\n        assert review.get('qualification_evidence'), 'missing runtime qualification'")
s=s.replace("    sessions=session_layout(args.name,order,args.timing)\n    for session in sessions:session['resource_sample_ms']=args.resource_sample_ms", "    sessions=[]\n    for i,item in enumerate(matrix):\n        session={'index':i,'variant':'low','baseline':('hot' if item['group'] in ('G2','G3','G4') else 'cold'),'architecture_group':item['group'],'timing':args.timing,'resource_sample_ms':args.resource_sample_ms,'session':args.name+'-'+str(i)+'-'+item['group'],'relative_dir':'sessions/'+str(i).zfill(2)+'-'+item['group'],'requests':item['requests'],'qualification':item.get('qualification',False),'extra_env':item.get('env',{}),'configuration':item}\n        sessions.append(session)")
s=s.replace("    for session in sessions:freeze_session(study,project,out/session['relative_dir'],session,args,meta,review,review_bytes)", "    for session in sessions:\n        local_args=argparse.Namespace(**vars(args));local_args.requests=session['requests'];local_args.np_level=session['extra_env'].get('NP_LEVEL',args.np_level);local_args.np_case=session['extra_env'].get('NP_CASE',args.np_case)\n        freeze_session(study,project,out/session['relative_dir'],session,local_args,meta,review,review_bytes)\n        put(out/session['relative_dir']/'full-session.json',session)")
s=s.replace("    out.mkdir(parents=True,exist_ok=False)", "    import fcntl\n    lock=open('/tmp/shimos-architecture-comparison-full-vm.lock','a');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n    active=subprocess.run(['pgrep','-af','[q]emu-system-x86_64'],capture_output=True,text=True)\n    assert not active.stdout.strip(),('another VM active',active.stdout)\n    out.mkdir(parents=True,exist_ok=False)\n    shutil.copy2(args.matrix,out/'preregistered-sessions.json')")
